// Combat corpus: runs the JVM oracle (../nonograms-katana/tools/oracle/run.sh fightgen / fight) on a fixed, seeded
// list of setups and writes one fight file per setup, plus index.json (name -> category, oracle args, save path).
// Categories: auto-kit, auto-bare, auto-gear, auto-short, start, prefs, near-boss, chain, scenario, save, profile
// (fightgen --profile: the game's own dungeon start for a player profile: the user's export, NK_SAVE, when present,
// and synthetic `savegen prog` profiles), and explore / explore-target (tools/explore.mjs: inputs generated by the
// JS engine's play policy, then replayed).
// Use test/make-fights.sh; see js/combat/PORTING.md -> Testing.
//
//   node test/make-fights.mjs [--out DIR] [--jobs N] [--only REGEX] [--list] [--force]
//
// Seeds come from a generator batch (default ~/.cache/nk-oracle/fx7, made by `run.sh batch DIR all 40 7`): only
// seeds the game generated without getting stuck, so every fightgen setup succeeds. Bosses for near: are the
// objective critters (bw.t) of those dumps. Existing files are kept unless --force.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { initTables, zw } from '../js/gen/index.js';
import { explore, exploreSpecs, targetSpecs, oracleArgs } from '../tools/explore.mjs';

const here = path.dirname(new URL(import.meta.url).pathname);
const RE = process.env.NK_RE || path.resolve(here, '../../nonograms-katana');
const RUN = path.join(RE, 'tools/oracle/run.sh');
const cache = path.join(os.homedir(), '.cache/nk-oracle');
const args = process.argv.slice(2);
const opt = (k, d) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : d; };
const OUT = opt('--out', path.join(cache, 'fights'));
const USER_SAVE = process.env.NK_SAVE || path.join(RE, 'saves/NonogramsKatana.zip');   // never copied anywhere
const PROF = path.join(cache, 'save/prof/synth');   // savegen prog profiles (made below when missing)
const SEEDS = opt('--seeds', path.join(cache, 'fx7'));
const JOBS = +opt('--jobs', Math.max(1, Math.min(8, os.cpus().length >> 1)));
const ONLY = opt('--only', null);
const force = args.includes('--force');
initTables(JSON.parse(fs.readFileSync(path.join(here, '../data/tables.json'), 'utf8')));

// ---- seeds and bosses per type -------------------------------------------------------------------
const byType = new Map();
for (const f of fs.readdirSync(SEEDS).sort()) {
	const m = /^(\d+)-(\d+)\.json$/.exec(f);
	if (!m) continue;
	const t = +m[1], seed = +m[2];
	if (!byType.has(t)) byType.set(t, []);
	byType.get(t).push({ seed, file: path.join(SEEDS, f) });
}
function bossOf(t) {
	for (const { seed, file } of byType.get(t) || []) {
		const lv = JSON.parse(fs.readFileSync(file, 'utf8'));
		if (lv.error) continue;
		const b = lv.critters.find((c) => zw.R.get(c.id)?.t && c.k === 2);
		if (b) return { seed, x: b.x, y: b.y, id: b.id };
	}
	return null;
}

// tiny LCG for the setup parameters (stable list across runs)
let rs = 20261109;
const rnd = (n) => { rs = (Math.imul(rs, 69069) + 1) | 0; return ((rs >>> 8) % n + n) % n; };

const specs = [];
const add = (name, cat, a, extra = {}) => specs.push({ name, cat, args: a, ...extra });
const scen = (n) => path.join(here, 'scenarios', `${n}.json`);

for (let t = 0; t < 27; t++) {
	const seeds = (byType.get(t) || []).map((s) => s.seed);
	if (seeds.length < 6) { console.error(`type ${t}: only ${seeds.length} seeds in ${SEEDS}`); continue; }
	const S = (i) => String(seeds[i % seeds.length]);
	const X = () => String(rnd(1 << 30));
	const lvl = () => String(2 + rnd(20));
	const gear = () => String(1 + rnd(4));
	for (let v = 0; v < 2; v++) {
		add(`${t}-autokit-${v}`, 'auto-kit', ['fightgen', String(t), S(v), X(), 'auto', '-', '--kit', '--level', lvl(), '--fuzz', '200', '--fuzzseed', String(1 + rnd(1000)), '--draws']);
		add(`${t}-autobare-${v}`, 'auto-bare', ['fightgen', String(t), S(2 + v), X(), 'auto', '-', '--level', lvl(), '--fuzz', '60', '--fuzzseed', String(1 + rnd(1000)), '--draws']);
	}
	add(`${t}-autogear`, 'auto-gear', ['fightgen', String(t), S(4), X(), 'auto', '-', '--kit', '--level', lvl(), '--gear', gear(), '--fuzz', '400', '--fuzzseed', String(1 + rnd(1000)), '--trace']);
	add(`${t}-autoshort`, 'auto-short', ['fightgen', String(t), S(5), X(), 'auto', '-', '--fuzz', '25', '--fuzzseed', String(1 + rnd(1000)), '--draws']);
	add(`${t}-start`, 'start', ['fightgen', String(t), S(6), X(), 'start', '-', '--kit', '--level', lvl(), '--fuzz', '300', '--fuzzseed', String(1 + rnd(1000)), '--draws']);
	add(`${t}-startbare`, 'start', ['fightgen', String(t), S(7), X(), 'start', '-', '--fuzz', '80', '--fuzzseed', String(1 + rnd(1000)), '--draws']);
	if (t % 3 === 0) add(`${t}-prefs`, 'prefs', ['fightgen', String(t), S(8), X(), 'auto', '-', '--kit', '--level', lvl(), '--run', '0', '--trapsindif', '0', '--fuzz', '150', '--fuzzseed', String(1 + rnd(1000)), '--draws']);
	const boss = bossOf(t);
	if (boss) {
		add(`${t}-boss`, 'near-boss', ['fightgen', String(t), String(boss.seed), X(), `near:${boss.x},${boss.y}`, '-', '--kit', '--level', String(15 + rnd(7)), '--gear', String(2 + rnd(3)), '--fuzz', '250', '--fuzzseed', String(1 + rnd(1000)), '--trace']);
		add(`${t}-bossweak`, 'near-boss', ['fightgen', String(t), String(boss.seed), X(), `near:${boss.x},${boss.y}`, scen('melee'), '--kit', '--level', '2', '--draws']);
	}
	// mid-fight save, then the game's loader (fight mode) continues it
	const sv = path.join(OUT, 'saves', `${t}-chain.dat`);
	const fz = String(1 + rnd(1000));
	add(`${t}-chain-a`, 'chain', ['fightgen', String(t), S(9), X(), 'auto', '-', '--kit', '--level', lvl(), '--fuzz', String(10 + rnd(30)), '--fuzzseed', fz, '--draws', '--save', sv]);
	add(`${t}-chain-b`, 'chain', ['fight', sv, '-', '--fuzz', '150', '--fuzzseed', String(1 + rnd(1000)), '--draws'], { after: `${t}-chain-a`, save: sv });
}

// hand-written scenarios (test/scenarios/*.json, symbolic targets resolved by the oracle) on a few families
const SC_TYPES = [8, 15, 19, 23];
for (const f of fs.readdirSync(path.join(here, 'scenarios')).sort()) {
	const n = f.replace(/\.json$/, '');
	if (n === 'melee') continue;
	for (const t of SC_TYPES) {
		const seeds = (byType.get(t) || []).map((s) => s.seed);
		if (!seeds.length) continue;
		add(`sc-${n}-${t}`, 'scenario', ['fightgen', String(t), String(seeds[10 % seeds.length]), String(rnd(1 << 30)), 'auto', scen(n), '--kit', '--level', String(8 + rnd(8)), '--gear', String(1 + rnd(2)), '--fuzz', '40', '--fuzzseed', String(1 + rnd(1000)), '--trace']);
	}
}

// exploration (tools/explore.mjs): whole dungeons played by the JS engine's policy (4 seeds per type; variant 3 without
// --kit2 and with --trapsindif 0), and targeted runs next to creatures with each ability / boss / NPC kind. The
// inputs are generated once into OUT/explore/<name>.inputs.json (kept unless --force), then replayed by the oracle
// with --cells (records also compare the tiles and the fog).
const EXPLORE = path.join(OUT, 'explore');
const exploreList = [
	...exploreSpecs({ types: [...Array(27).keys()], seeds: 4, seedDir: SEEDS }).map((x) => ({ ...x, cat: 'explore' })),
	...targetSpecs({ seedDir: SEEDS }).map((x) => ({ ...x, cat: 'explore-target' })),
];
for (const x of exploreList) {
	const inFile = path.join(EXPLORE, `${x.name}.inputs.json`);
	add(x.name, x.cat, oracleArgs(x, inFile, null, ['--draws', '--cells']), { explore: x, inputs: inFile });
}

// synthetic mid-dungeon saves of test/save.mjs (vj0.n2 output), continued by the loader
const synth = path.join(cache, 'save/synth');
if (fs.existsSync(synth)) {
	for (const f of fs.readdirSync(synth).sort()) {
		if (!/^hw-.*\.dat$/.test(f)) continue;
		const sv = path.join(synth, f);
		add(`save-${f.replace(/\.dat$/, '')}`, 'save', ['fight', sv, '-', '--kit', '--fuzz', '120', '--fuzzseed', String(1 + rnd(1000)), '--draws'], { save: sv });
	}
}

// player profiles (fightgen --profile): the game's PageDungeon.C entry (pack, MP, familiars, fee, generation with the
// profile's progress) for several heroes. The user's export is in town with hero 19 (level 2) selected; it unlocks
// types 0 2 3 6 9 12 15 16 17 19 20 (17 needs a fee it cannot pay: the oracle refuses it). The synthetic `prog`
// profiles unlock everything and carry familiars, armour 254, taming foods, a locked item and research 37
// (flamethrowers); their heroes get --level 20 after entry (longer fights; the pack is entry's).
const profileSpecs = [];
if (fs.existsSync(USER_SAVE)) {
	for (const [hero, t, at, extra] of [
		[19, 0, 'start', []], [19, 15, 'auto', []], [19, 2, 'auto', []],
		[0, 2, 'auto', []], [0, 6, 'auto', ['--premium']], [0, 12, 'start', []], [0, 20, 'auto', ['--pets', '190:5:1:236:2,191:9:2:251:1']],
		[0, 16, 'auto', []], [3, 19, 'start', []], [3, 3, 'auto', []], [1, 12, 'auto', []], [1, 9, 'auto', ['--trace']],
	]) profileSpecs.push({ name: `pf-user-h${hero}-${t}`, save: USER_SAVE, hero, t, at, extra });
}
for (const [sv, hero, t, at, extra] of [
	['prog-0-7', 0, 8, 'auto', []], ['prog-0-7', 0, 23, 'auto', ['--premium']], ['prog-0-7', 0, 19, 'start', ['--trace']],
	['prog-0-7', 0, 4, 'auto', []], ['prog-0-7', 2, 15, 'auto', []], ['prog-0-7', 1, 26, 'auto', ['--kit']],
	['prog-0-11', 0, 21, 'auto', []], ['prog-0-11', 0, 24, 'start', ['--premium']],
]) profileSpecs.push({ name: `pf-${sv}-h${hero}-${t}`, save: path.join(PROF, `${sv}.dat`), prog: sv, hero, t, at, extra: [...extra, '--level', '20'] });
profileSpecs.forEach((p, i) => {
	const seeds = (byType.get(p.t) || []).map((s) => s.seed);
	if (!seeds.length) return;
	const fuzz = p.hero === 19 ? 120 : 200;
	add(p.name, 'profile', ['fightgen', String(p.t), String(seeds[(11 + i) % seeds.length]), String(rnd(1 << 30)), p.at, '-',
		'--profile', p.save, '--hero', String(p.hero), ...p.extra, '--fuzz', String(fuzz), '--fuzzseed', String(1 + rnd(1000)),
		...(p.extra.includes('--trace') ? [] : ['--draws'])], { save: p.save, prog: p.prog });
});

// ---- run -----------------------------------------------------------------------------------------
if (args.includes('--list')) {
	for (const s of specs) console.log(s.name.padEnd(22), s.args.join(' '));
	console.log(`${specs.length} fights`);
	process.exit(0);
}
fs.mkdirSync(path.join(OUT, 'saves'), { recursive: true });
const todo = specs.filter((s) => (!ONLY || new RegExp(ONLY).test(s.name)) && (force || !fs.existsSync(path.join(OUT, `${s.name}.json`))));
// synthetic profiles for the profile category (the game's writer: SaveHarness savegen prog)
for (const sv of new Set(todo.filter((s) => s.prog).map((s) => s.prog))) {
	const f = path.join(PROF, `${sv}.dat`);
	if (fs.existsSync(f) && !force) continue;
	fs.mkdirSync(PROF, { recursive: true });
	const [, type, seed] = sv.split('-');
	await new Promise((resolve, reject) => {
		const p = spawn(RUN, ['savegen', 'prog', type, seed, PROF], { stdio: ['ignore', 'ignore', 'inherit'] });
		p.on('close', (code) => (code === 0 ? resolve() : reject(new Error(`savegen prog ${type} ${seed}: exit ${code}`))));
	});
}
// exploration inputs first (JS engine, in-process)
fs.mkdirSync(EXPLORE, { recursive: true });
for (const s of todo) {
	if (!s.explore || (!force && fs.existsSync(s.inputs))) continue;
	const r = explore(s.explore, { pseed: s.explore.pseed, max: s.explore.max });
	if (r.error) { console.error(`explore ${s.name}: ${r.error}`); continue; }
	fs.writeFileSync(s.inputs, JSON.stringify(r.inputs));
	process.stderr.write(`  explore ${s.name}: ${r.inputs.length} inputs, st=${r.stats.st}\n`);
}
const index = fs.existsSync(path.join(OUT, 'index.json')) ? JSON.parse(fs.readFileSync(path.join(OUT, 'index.json'), 'utf8')) : {};
for (const s of specs) index[s.name] = { cat: s.cat, args: s.args, save: s.save || null, ...(s.inputs ? { inputs: s.inputs } : {}) };

function runOne(s) {
	return new Promise((resolve) => {
		const out = path.join(OUT, `${s.name}.json`);
		const a = s.args.slice();
		a.splice(s.args[0] === 'fight' ? 3 : 6, 0, out);   // [out.json] follows the inputs argument
		const p = spawn(RUN, a, { stdio: ['ignore', 'ignore', 'pipe'] });
		let err = '';
		p.stderr.on('data', (d) => { err += d; });
		p.on('close', (code) => resolve({ s, code, err: err.trim().split('\n').pop() }));
	});
}

const t0 = Date.now();
let done = 0, failed = 0;
const pending = new Map(todo.map((s) => [s.name, s]));
const running = new Set();
await new Promise((finish) => {
	const pump = () => {
		if (!pending.size && !running.size) return finish();
		for (const [name, s] of pending) {
			if (running.size >= JOBS) break;
			if (s.after && (pending.has(s.after) || running.has(s.after))) continue;   // chain: save first
			pending.delete(name);
			running.add(name);
			runOne(s).then(({ code, err }) => {
				running.delete(name);
				done++;
				if (code !== 0) { failed++; console.error(`FAIL ${name}: exit ${code}: ${err}`); }
				if (done % 25 === 0 || !pending.size) process.stderr.write(`  ${done}/${todo.length} (${((Date.now() - t0) / 1000) | 0}s)\n`);
				pump();
			});
		}
	};
	pump();
});
fs.writeFileSync(path.join(OUT, 'index.json'), JSON.stringify(index, null, 1));

// ---- stats ---------------------------------------------------------------------------------------
let files = 0, inputs = 0, errors = 0, draws = 0;
const cats = {}, sts = {}, ins = {};
for (const f of fs.readdirSync(OUT)) {
	if (!f.endsWith('.json') || f === 'index.json') continue;
	const j = JSON.parse(fs.readFileSync(path.join(OUT, f), 'utf8'));
	files++;
	const c = index[f.slice(0, -5)]?.cat || '?';
	cats[c] = (cats[c] || 0) + 1;
	if (j.error) { errors++; continue; }
	inputs += j.summary.inputs;
	draws += j.summary.xDraws;
	sts[j.summary.st] = (sts[j.summary.st] || 0) + 1;
	for (const s of j.steps) ins[s.in.t] = (ins[s.in.t] || 0) + 1;
}
console.log(`${OUT}: ${files} fights (${failed} runs failed, ${errors} setup errors), ${inputs} inputs, ${draws} x draws`);
console.log('  by category', JSON.stringify(cats));
console.log('  final status', JSON.stringify(sts));
console.log('  inputs', JSON.stringify(ins));
